mapper.select:
SELECT * FROM easybuy_product
WHERE is_delete = 0

    AND name LIKE CONCAT('%', #{name}, '%')


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}


    AND category_level1_id = #{categoryLevel1Id}


    AND category_level2_id = #{categoryLevel2Id}


    AND category_level3_id = #{categoryLevel3Id}

ORDER BY create_time DESC, id DESC

SELECT *
FROM easybuy_product
WHERE is_delete = 0
  AND category_level1_id = #{categoryLevel1Id}
ORDER BY id DESC
    LIMIT #{limit}

SELECT *
FROM easybuy_product
WHERE is_delete = 0
  AND category_level2_id = #{categoryLevel2Id}
ORDER BY id DESC
    LIMIT #{limit}

SELECT *
FROM easybuy_product
WHERE is_delete = 0
  AND category_level3_id = #{categoryLevel3Id}
ORDER BY id DESC
    LIMIT #{limit}

mapper.update:
UPDATE easybuy_product
SET is_delete = 1
WHERE id = #{id}

UPDATE easybuy_product
SET stock = stock - #{quantity},
    pre_stock = pre_stock + #{quantity}
WHERE id = #{id}
  AND stock >= #{quantity}

UPDATE easybuy_product
SET pre_stock = pre_stock - #{quantity}
WHERE id = #{id}
  AND pre_stock >= #{quantity}

UPDATE easybuy_product
SET stock = stock + #{quantity},
    pre_stock = pre_stock - #{quantity}
WHERE id = #{id}
  AND pre_stock >= #{quantity}

UPDATE easybuy_product
SET stock = stock + #{quantity}
WHERE id = #{id}
